using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // The MCP SDK resolves constructor parameters from the DI container.
    // IHttpClientFactory is registered via AddHttpClient(); the SDK creates
    // a scoped instance of this class for each tool invocation.
    public WeatherTools(HttpClient http)
    {
        _http = http;
        _http.BaseAddress ??= new Uri("https://api.open-meteo.com");
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var forecast = await _http.GetFromJsonAsync<WeatherResponse>(url);
        if (forecast?.Current is null)
            return "Unable to retrieve weather data.";

        var c = forecast.Current;
        return $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public async Task<string> GeocodeCity(
        [Description("City name to look up")] string city)
    {
        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";

        var result = await _http.GetFromJsonAsync<GeocodeResponse>(url);
        if (result?.Results is not [var first, ..])
            return $"No results found for '{city}'.";

        return $"{first.Name}: lat={first.Latitude}, lon={first.Longitude}";
    }
}

// --- DTOs ---------------------------------------------------------------

public sealed class WeatherResponse
{
    [JsonPropertyName("current")]
    public CurrentWeather? Current { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; set; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; set; }
}

public sealed class GeocodeResponse
{
    [JsonPropertyName("results")]
    public List<GeoResult>? Results { get; set; }
}

public sealed class GeoResult
{
    [JsonPropertyName("name")]
    public string Name { get; set; } = "";

    [JsonPropertyName("latitude")]
    public double Latitude { get; set; }

    [JsonPropertyName("longitude")]
    public double Longitude { get; set; }
}

